import {TriangleDownIcon} from '@primer/octicons-react'
import {Button, FormControl, SelectPanel, type SelectPanelItemInput} from '@primer/react'
import {useId, useMemo, useState} from 'react'

interface FontPickerItemProps {
  label: string
  value?: string
  onChange: (value: string) => void
  items: readonly string[]
}

export function FontPickerItem({label, items, value, onChange}: FontPickerItemProps) {
  const [open, setOpen] = useState(false)
  const [filter, setFilter] = useState('')

  const filteredItems = useMemo(() => {
    return items
      .filter(item => item.toLowerCase().includes(filter.toLowerCase()))
      .map(item => ({
        id: item,
        text: item,
      }))
  }, [items, filter])

  const selected = useMemo(() => {
    const font = items.find(item => item === value)

    if (!font) {
      return undefined
    }

    return {id: font}
  }, [value, items])

  const labelId = useId()
  const valueId = useId()
  const anchorId = useId()

  return (
    <FormControl>
      <FormControl.Label id={labelId} htmlFor={anchorId} visuallyHidden>
        {label}
      </FormControl.Label>
      <SelectPanel
        renderAnchor={({children, ...anchorProps}) => {
          return (
            <Button
              size="small"
              block
              alignContent="start"
              {...anchorProps}
              trailingAction={TriangleDownIcon}
              aria-haspopup="dialog"
              id={anchorId}
              aria-labelledby={`${labelId} ${valueId}`}
            >
              <span id={valueId}>{selected?.id ?? 'Default'}</span>
            </Button>
          )
        }}
        showSelectedOptionsFirst
        placeholder="Select a font"
        placeholderText="Select a font"
        open={open}
        onOpenChange={setOpen}
        items={filteredItems}
        selected={selected}
        onSelectedChange={(font: unknown) => {
          if (font) {
            onChange((font as SelectPanelItemInput & {id: string}).id)
          }
        }}
        onFilterChange={setFilter}
        overlayProps={{
          maxHeight: 'large',
        }}
      />
    </FormControl>
  )
}

try{ FontPickerItem.displayName ||= 'FontPickerItem' } catch {}